-- Complete published itinerary timelines with one visible row per travel day.
-- Fact-check basis: official Sri Lanka Tourism attraction themes and pages,
-- UNESCO Sri Lanka World Heritage listings, DWC protected-area guidance, and
-- SLTDA 2026 source-market reporting used for route-market prioritisation.

SET NAMES utf8mb4;

DROP TEMPORARY TABLE IF EXISTS ict_itinerary_day_seed;

CREATE TEMPORARY TABLE ict_itinerary_day_seed (
    itinerary_slug VARCHAR(255) NOT NULL,
    day_number INT UNSIGNED NOT NULL,
    day_end INT UNSIGNED NOT NULL,
    title VARCHAR(255) NOT NULL,
    summary TEXT NULL,
    overnight_location VARCHAR(150) NULL,
    travel_time VARCHAR(100) NULL,
    PRIMARY KEY (itinerary_slug, day_number)
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO ict_itinerary_day_seed
    (itinerary_slug, day_number, day_end, title, summary, overnight_location, travel_time)
VALUES
('sri-lanka-wildlife-safari-itinerary-7-days', 1, 1, 'Arrival and Udawalawe transfer', 'Meet your private chauffeur at the airport, settle into the vehicle, and continue toward Udawalawe with comfort stops based on flight time. Keep the first evening light so the safari days start fresh.', 'Udawalawe', 'Airport to Udawalawe 4.5-5.5 hours'),
('sri-lanka-wildlife-safari-itinerary-7-days', 2, 2, 'Udawalawe elephant safari', 'Plan an early or late Udawalawe National Park safari for elephant-focused wildlife viewing, with optional Elephant Transit Home timing if it fits the day. Keep the middle of the day for rest near the reservoir.', 'Udawalawe', 'Local safari drives'),
('sri-lanka-wildlife-safari-itinerary-7-days', 3, 3, 'Bundala wetlands and Yala base', 'Travel toward Tissamaharama or Yala. Add Bundala wetland birding if conditions and energy suit, or keep the afternoon soft before the next dawn safari.', 'Tissamaharama or Yala', 'Udawalawe to Yala area 3-4 hours'),
('sri-lanka-wildlife-safari-itinerary-7-days', 4, 4, 'Yala National Park safari', 'Use a dawn safari window for Yala, one of Sri Lanka''s best-known wildlife parks, with realistic expectations for leopard, elephant, crocodile, deer, and birdlife. The exact block can be confirmed locally.', 'Tissamaharama or Yala', 'Safari-based local travel'),
('sri-lanka-wildlife-safari-itinerary-7-days', 5, 5, 'Yala to the south coast', 'Move from the dry-zone safari landscape toward the south coast, choosing a Tangalle, Mirissa, Weligama, or Galle stop depending on beach preference and hotel style.', 'Galle, Unawatuna, or south coast', 'Yala to Galle area 4-5 hours'),
('sri-lanka-wildlife-safari-itinerary-7-days', 6, 6, 'Galle Fort and coastal time', 'Walk UNESCO-listed Galle Fort, then use the afternoon for Unawatuna, Hikkaduwa, Weligama, Mirissa, or a quiet coastal base. This gives the route a heritage finish after the wildlife focus.', 'Galle or south coast', 'Local coastal travel'),
('sri-lanka-wildlife-safari-itinerary-7-days', 7, 7, 'Colombo or airport departure', 'Return by expressway for Colombo, Negombo, or the airport, adding a short city, food, or shopping stop only if the flight time allows it comfortably.', 'Departure or Colombo', 'Galle to airport 2-3 hours by expressway'),

('sri-lanka-itinerary-5-days', 1, 1, 'Arrival and Negombo recovery', 'Start with airport pickup and a short transfer to Negombo or Colombo. Keep the day flexible for flight delays, hotel check-in, a lagoon-side walk, or a light city meal.', 'Negombo or Colombo', 'Airport transfer 20-90 minutes'),
('sri-lanka-itinerary-5-days', 2, 2, 'Sigiriya and Dambulla', 'Drive to the Cultural Triangle for Sigiriya, Dambulla Cave Temple, or a village-style experience depending on arrival time. These are strong first-time Sri Lanka anchors without overloading the day.', 'Sigiriya or Habarana', 'Negombo to Sigiriya 4-5 hours'),
('sri-lanka-itinerary-5-days', 3, 3, 'Kandy culture route', 'Continue to Kandy through Matale or nearby spice and craft stops. Visit the Temple of the Sacred Tooth Relic area, the lake, or Peradeniya gardens with timing adjusted around traffic.', 'Kandy', 'Sigiriya to Kandy 2.5-3.5 hours'),
('sri-lanka-itinerary-5-days', 4, 4, 'Tea country and scenic hills', 'Use the day for tea country scenery around Nuwara Eliya, Ramboda, or an Ella-style hill-country extension if the route and hotel choices make sense. Keep the focus on tea, waterfalls, and cooler highland views.', 'Nuwara Eliya, Kandy, or Ella', 'Kandy to tea country 2-4 hours'),
('sri-lanka-itinerary-5-days', 5, 5, 'Galle, Colombo, or airport finish', 'Finish according to flight timing: a faster Colombo or airport return, or a longer south-coast finish with Galle Fort if the schedule allows. The private route should avoid forcing too many regions into one short trip.', 'Departure, Colombo, or Galle', 'Varies by final route'),

('sri-lanka-itinerary-7-days', 1, 1, 'Arrival and soft landing', 'Meet your chauffeur at the airport and recover in Negombo or Colombo. Use the day for rest, a light coastal stop, or a short city introduction rather than a long sightseeing list.', 'Negombo or Colombo', 'Airport transfer 20-90 minutes'),
('sri-lanka-itinerary-7-days', 2, 2, 'Sigiriya and Dambulla', 'Travel to the Cultural Triangle for Sigiriya, Dambulla, or a relaxed local experience. Keep the climb or cave visit at a sensible time of day for heat and crowd comfort.', 'Sigiriya or Habarana', 'Negombo to Sigiriya 4-5 hours'),
('sri-lanka-itinerary-7-days', 3, 3, 'Polonnaruwa or elephant safari', 'Choose a heritage-led day at Polonnaruwa or an afternoon elephant safari at Minneriya, Kaudulla, or Eco Park depending on local wildlife movement. This keeps the route flexible and realistic.', 'Sigiriya or Habarana', 'Local loop 1-3 hours plus visits'),
('sri-lanka-itinerary-7-days', 4, 4, 'Kandy via Matale', 'Continue to Kandy, using Matale, gardens, craft stops, or the Temple of the Sacred Tooth Relic area as timing allows. Stay central so the evening is easy.', 'Kandy', 'Sigiriya to Kandy 2.5-3.5 hours'),
('sri-lanka-itinerary-7-days', 5, 5, 'Tea country and Ella scenery', 'Move through tea country by private scenic drive or a selected train segment if tickets and timing work. Add tea estates, waterfalls, Nine Arch Bridge, or Little Adam''s Peak based on fitness and weather.', 'Nuwara Eliya or Ella', 'Kandy to hill country 2.5-5 hours'),
('sri-lanka-itinerary-7-days', 6, 6, 'Safari or south-coast transfer', 'Choose one focused highlight instead of rushing both: Udawalawe or Yala for safari, or a direct move to Galle and the south coast for beach and heritage time.', 'Udawalawe, Yala, or Galle', 'Ella to safari/coast 2.5-5 hours'),
('sri-lanka-itinerary-7-days', 7, 7, 'Galle, Colombo, or airport', 'Use the final day for Galle Fort, a beach stop, or the expressway return to Colombo and the airport. The route should stay aligned with departure time.', 'Departure or Colombo', 'Galle to airport 2-3 hours by expressway'),

('sri-lanka-itinerary-10-days', 1, 1, 'Arrival and easy recovery', 'Airport pickup, hotel check-in, and a light Negombo or Colombo introduction. This protects the first day for long-haul recovery before the classic route begins.', 'Negombo or Colombo', 'Airport transfer 20-90 minutes'),
('sri-lanka-itinerary-10-days', 2, 2, 'Cultural Triangle transfer', 'Drive to Sigiriya or Habarana and settle into the Cultural Triangle. Add Dambulla Cave Temple or a village stop if arrival time and heat conditions suit.', 'Sigiriya or Habarana', 'Negombo to Sigiriya 4-5 hours'),
('sri-lanka-itinerary-10-days', 3, 3, 'Sigiriya, Polonnaruwa, or elephant safari', 'Use this full day for Sigiriya Rock or Pidurangala, Polonnaruwa heritage, and/or an afternoon Minneriya or Kaudulla elephant safari. The final mix should match pace, season, and fitness.', 'Sigiriya or Habarana', 'Local loop 1-3 hours plus visits'),
('sri-lanka-itinerary-10-days', 4, 4, 'Kandy culture', 'Transfer to Kandy with a practical stop in Matale, Aluvihare, a spice garden, or Peradeniya depending on interest. End with the lake or Temple of the Sacred Tooth Relic area.', 'Kandy', 'Sigiriya to Kandy 2.5-3.5 hours'),
('sri-lanka-itinerary-10-days', 5, 5, 'Nuwara Eliya tea country', 'Continue into the tea country for estates, viewpoints, waterfalls, and cooler highland scenery. The day works best when the train or drive is treated as part of the experience.', 'Nuwara Eliya or tea country', 'Kandy to Nuwara Eliya 2.5-3.5 hours'),
('sri-lanka-itinerary-10-days', 6, 6, 'Ella scenic day', 'Travel onward to Ella or Haputale for Nine Arch Bridge, Little Adam''s Peak, tea viewpoints, and a relaxed hill-country evening. Keep activities weather-aware.', 'Ella or Haputale', 'Nuwara Eliya to Ella 2-3 hours by road'),
('sri-lanka-itinerary-10-days', 7, 7, 'Safari base transfer', 'Descend from the hills toward Udawalawe or Yala. Choose Udawalawe for elephant-focused families and Yala for a more leopard-focused dry-zone safari plan.', 'Udawalawe, Tissamaharama, or Yala', 'Ella to safari base 2.5-3.5 hours'),
('sri-lanka-itinerary-10-days', 8, 8, 'Safari and south-coast move', 'Take a dawn or late-afternoon safari, then continue toward Tangalle, Mirissa, Weligama, Unawatuna, or Galle. The day should leave space after the early start.', 'Galle, Tangalle, or south coast', 'Safari base to coast 2-4 hours'),
('sri-lanka-itinerary-10-days', 9, 9, 'Galle Fort and beach time', 'Walk Galle Fort, then choose south-coast time around Unawatuna, Hikkaduwa, Weligama, Mirissa, or a quieter beach hotel. This balances heritage with rest.', 'Galle, Unawatuna, or south coast', 'Local coastal travel'),
('sri-lanka-itinerary-10-days', 10, 10, 'Airport or Colombo departure', 'Return by expressway for Colombo, Negombo, or the airport. Add a final meal, market, or shopping stop only if flight timing leaves a safe buffer.', 'Departure or Colombo', 'Galle to airport 2-3 hours by expressway'),

('sri-lanka-itinerary-12-days', 1, 1, 'Arrival and coastal recovery', 'Begin with airport pickup and a short recovery stay in Negombo or Colombo. Keep the first day simple for long-haul guests and late arrivals.', 'Negombo or Colombo', 'Airport transfer 20-90 minutes'),
('sri-lanka-itinerary-12-days', 2, 2, 'Sigiriya transfer and Dambulla', 'Travel to Sigiriya or Habarana, adding Dambulla Cave Temple or a slow local stop if timing works. This starts the route with Sri Lanka''s heritage core.', 'Sigiriya or Habarana', 'Negombo to Sigiriya 4-5 hours'),
('sri-lanka-itinerary-12-days', 3, 3, 'Sigiriya, Polonnaruwa, and elephants', 'Use the full Cultural Triangle day for Sigiriya or Pidurangala, Polonnaruwa if heritage is a priority, and an elephant safari only if the pace remains comfortable.', 'Sigiriya or Habarana', 'Local loop 1-3 hours plus visits'),
('sri-lanka-itinerary-12-days', 4, 4, 'Kandy via Matale', 'Move to Kandy with flexible stops for gardens, spice, crafts, or a temple visit. Keep the evening central for the lake and cultural atmosphere.', 'Kandy', 'Sigiriya to Kandy 2.5-3.5 hours'),
('sri-lanka-itinerary-12-days', 5, 5, 'Nuwara Eliya tea country', 'Continue into the tea region for a factory visit, highland viewpoints, and waterfall stops. Use the private vehicle to manage weather and timing.', 'Nuwara Eliya or tea country', 'Kandy to Nuwara Eliya 2.5-3.5 hours'),
('sri-lanka-itinerary-12-days', 6, 6, 'Ella scenic transfer', 'Travel toward Ella by scenic road or a selected train segment if available. Add Nine Arch Bridge, tea viewpoints, or an easy evening in town.', 'Ella', 'Nuwara Eliya to Ella 2-3 hours by road'),
('sri-lanka-itinerary-12-days', 7, 7, 'Ella soft adventure', 'Use a second hill-country day for Little Adam''s Peak, Ravana Falls, tea estates, or a slower cafe-and-viewpoint schedule. This prevents the route becoming transfer-heavy.', 'Ella', 'Local hill-country travel'),
('sri-lanka-itinerary-12-days', 8, 8, 'Safari base transfer', 'Descend to Yala, Tissamaharama, or Udawalawe for the wildlife portion. Choose the park based on elephant focus, leopard interest, family comfort, and current conditions.', 'Yala, Tissamaharama, or Udawalawe', 'Ella to safari base 2.5-3.5 hours'),
('sri-lanka-itinerary-12-days', 9, 9, 'Safari and Galle transfer', 'Take a safari at dawn or late afternoon, then continue toward Galle or the south coast with enough time to rest after the early start.', 'Galle or south coast', 'Safari base to Galle 3.5-5 hours'),
('sri-lanka-itinerary-12-days', 10, 10, 'Galle Fort and south-coast beaches', 'Explore UNESCO-listed Galle Fort, then use Unawatuna, Hikkaduwa, Weligama, or Mirissa for beach time based on season and hotel style.', 'Galle, Unawatuna, or south coast', 'Local coastal travel'),
('sri-lanka-itinerary-12-days', 11, 11, 'Beach, wellness, or slow coast day', 'Keep one flexible coastal day for beach, food, wellness, surf lessons, whale watching in season, or a slower boutique-hotel finish.', 'South or west coast', 'Local coastal travel'),
('sri-lanka-itinerary-12-days', 12, 12, 'Airport departure', 'Return to Colombo, Negombo, or the airport by expressway, allowing a safe buffer for check-in and traffic around the city.', 'Departure or Colombo', 'South coast to airport 2-4 hours'),

('sri-lanka-itinerary-14-days', 1, 1, 'Arrival and Negombo recovery', 'Meet your chauffeur and settle near the airport or Colombo. Keep the first evening light so the two-week route starts with energy and flexibility.', 'Negombo or Colombo', 'Airport transfer 20-90 minutes'),
('sri-lanka-itinerary-14-days', 2, 2, 'Anuradhapura or Sigiriya approach', 'Begin the heritage section with Anuradhapura for sacred-city depth or travel straight to Sigiriya if the group prefers a tighter classic route.', 'Anuradhapura, Sigiriya, or Habarana', 'Negombo to Cultural Triangle 4-5.5 hours'),
('sri-lanka-itinerary-14-days', 3, 3, 'Sigiriya, Dambulla, and elephant country', 'Use the day for Sigiriya, Dambulla Cave Temple, and a possible afternoon elephant safari at Minneriya, Kaudulla, or Eco Park based on local movement.', 'Sigiriya or Habarana', 'Local loop 1-3 hours plus visits'),
('sri-lanka-itinerary-14-days', 4, 4, 'Polonnaruwa and rural Cultural Triangle', 'Add Polonnaruwa for ancient-city context or keep the day slower with village, lake, and local food experiences. This gives the route more depth than a rushed one-night stop.', 'Sigiriya or Habarana', 'Local loop 2-3 hours plus visits'),
('sri-lanka-itinerary-14-days', 5, 5, 'Kandy transfer', 'Move to Kandy with Matale, gardens, craft, or temple stops selected around timing. Stay central for an easy evening near the lake.', 'Kandy', 'Sigiriya to Kandy 2.5-3.5 hours'),
('sri-lanka-itinerary-14-days', 6, 6, 'Nuwara Eliya and tea estates', 'Travel through the hill country for tea estates, waterfalls, viewpoints, and a cooler highland stay. The private drive lets the route pause where the weather is best.', 'Nuwara Eliya or tea country', 'Kandy to Nuwara Eliya 2.5-3.5 hours'),
('sri-lanka-itinerary-14-days', 7, 7, 'Ella scenic route', 'Continue to Ella or Haputale by road or selected rail segment if available. Use the afternoon for Nine Arch Bridge, tea viewpoints, or an easy town evening.', 'Ella or Haputale', 'Nuwara Eliya to Ella 2-3 hours by road'),
('sri-lanka-itinerary-14-days', 8, 8, 'Ella and Haputale slow day', 'Protect one slower hill-country day for Little Adam''s Peak, Lipton''s Seat, Ravana Falls, or relaxed viewpoint time. This is especially useful for Europe, North America, and Australia guests.', 'Ella or Haputale', 'Local hill-country travel'),
('sri-lanka-itinerary-14-days', 9, 9, 'Safari base transfer', 'Descend toward Yala, Tissamaharama, or Udawalawe. Choose the park based on wildlife goals, family comfort, and the onward beach route.', 'Yala, Tissamaharama, or Udawalawe', 'Ella to safari base 2.5-3.5 hours'),
('sri-lanka-itinerary-14-days', 10, 10, 'Safari and Tangalle coast', 'Take a dawn or late-afternoon safari, then move toward Tangalle, Hiriketiya, or another south-coast base for rest after the early start.', 'Tangalle, Hiriketiya, or south coast', 'Safari base to coast 2-4 hours'),
('sri-lanka-itinerary-14-days', 11, 11, 'Galle Fort and south-coast heritage', 'Continue west to Galle, walk the Fort, and choose Unawatuna, Weligama, Mirissa, or Hikkaduwa based on the preferred beach mood.', 'Galle or south coast', 'Tangalle to Galle 2-3 hours'),
('sri-lanka-itinerary-14-days', 12, 12, 'South or west coast rest day', 'Keep a true beach and wellness day for surf, food, swimming conditions in season, whale watching in season, or boutique-hotel downtime.', 'South or west coast', 'Local coastal travel'),
('sri-lanka-itinerary-14-days', 13, 13, 'Bentota, Colombo, or final beach base', 'Move closer to the airport through Bentota, Kalutara, or Colombo depending on flight time. Add a river, garden, food, or shopping stop only if it improves the route.', 'Bentota, Colombo, or Negombo', 'South coast to west coast 1.5-3.5 hours'),
('sri-lanka-itinerary-14-days', 14, 14, 'Departure day', 'Return to the airport with a safe check-in buffer. Keep any final sightseeing short and close to the route.', 'Departure', 'Final transfer varies by hotel'),

('sri-lanka-honeymoon-itinerary-12-days', 1, 1, 'Boutique arrival recovery', 'Begin with a private airport welcome and a relaxed Negombo or Colombo boutique stay. Keep the day quiet for recovery, a gentle dinner, or a short coastal walk.', 'Negombo or Colombo', 'Airport transfer 20-90 minutes'),
('sri-lanka-honeymoon-itinerary-12-days', 2, 2, 'Sigiriya luxury lodge transfer', 'Travel to Sigiriya or Habarana and check into a lodge-style base. Add Dambulla or a private village experience only if the arrival rhythm feels easy.', 'Sigiriya or Habarana', 'Negombo to Sigiriya 4-5 hours'),
('sri-lanka-honeymoon-itinerary-12-days', 3, 3, 'Sigiriya, Pidurangala, or private heritage day', 'Choose Sigiriya Rock, Pidurangala at sunrise or sunset, Dambulla Cave Temple, or a slower privately guided heritage day. Avoid overfilling the first romantic highlight day.', 'Sigiriya or Habarana', 'Local Cultural Triangle travel'),
('sri-lanka-honeymoon-itinerary-12-days', 4, 4, 'Kandy cultural evening', 'Move to Kandy with scenic and cultural stops chosen around comfort. The evening can focus on the lake, Temple of the Sacred Tooth Relic area, or a special dinner.', 'Kandy', 'Sigiriya to Kandy 2.5-3.5 hours'),
('sri-lanka-honeymoon-itinerary-12-days', 5, 5, 'Tea country bungalow', 'Continue to the tea country for a bungalow or boutique hotel stay, tea estate views, waterfalls, and cooler evenings. Keep the schedule selective so the property time matters.', 'Nuwara Eliya or tea country', 'Kandy to tea country 2.5-3.5 hours'),
('sri-lanka-honeymoon-itinerary-12-days', 6, 6, 'Ella scenery and viewpoints', 'Travel toward Ella or Haputale for Nine Arch Bridge, Little Adam''s Peak, tea viewpoints, or a scenic rail segment if it fits. This day should feel scenic rather than rushed.', 'Ella or Haputale', 'Tea country to Ella 2-3 hours by road'),
('sri-lanka-honeymoon-itinerary-12-days', 7, 7, 'Safari lodge transfer', 'Descend to Yala, Udawalawe, or a nearby safari lodge. Choose the park based on desired wildlife style and the comfort level wanted after the hills.', 'Yala, Tissamaharama, or Udawalawe', 'Ella to safari base 2.5-3.5 hours'),
('sri-lanka-honeymoon-itinerary-12-days', 8, 8, 'Safari and Tangalle coast', 'Take an early safari with realistic wildlife expectations, then continue to Tangalle, Hiriketiya, or a quiet coastal retreat for a softer beach transition.', 'Tangalle, Hiriketiya, or south coast', 'Safari base to coast 2-4 hours'),
('sri-lanka-honeymoon-itinerary-12-days', 9, 9, 'Galle Fort boutique stay', 'Move to Galle for a boutique Fort stay or nearby beach hotel. Walk the ramparts, lighthouse area, shops, and cafes in the cooler part of the day.', 'Galle or Unawatuna', 'Tangalle to Galle 2-3 hours'),
('sri-lanka-honeymoon-itinerary-12-days', 10, 10, 'Beach and wellness day', 'Keep a genuine rest day for spa time, beach, private dining, surf lessons, or a seasonal whale-watching option from Mirissa if sea conditions and timing are right.', 'Galle, Mirissa, or south coast', 'Local coastal travel'),
('sri-lanka-honeymoon-itinerary-12-days', 11, 11, 'Private beach finish', 'Use the final full day for a slower south or west coast base, with hotel time protected instead of adding another long excursion.', 'South or west coast', 'Local or short coastal transfer'),
('sri-lanka-honeymoon-itinerary-12-days', 12, 12, 'Departure with relaxed buffer', 'Return to Colombo, Negombo, or the airport with enough buffer for check-in. Add a final lunch or shopping stop only if it stays stress-free.', 'Departure or Colombo', 'Coast to airport 2-4 hours'),

('sri-lanka-family-itinerary-10-days', 1, 1, 'Family arrival recovery', 'Start with a short transfer, early hotel check-in if possible, pool time, snacks, and a simple dinner. Keep the day easy for children and long-haul arrivals.', 'Negombo or Colombo', 'Airport transfer 20-90 minutes'),
('sri-lanka-family-itinerary-10-days', 2, 2, 'Sigiriya family base', 'Travel to Sigiriya or Habarana, choosing a hotel with pool time and space. Add Dambulla or a village stop only if children have energy after the drive.', 'Sigiriya or Habarana', 'Negombo to Sigiriya 4-5 hours'),
('sri-lanka-family-itinerary-10-days', 3, 3, 'Dambulla, village life, or elephant safari', 'Build the day around children''s energy: Dambulla Cave Temple, a village-style lunch, and an afternoon elephant safari at Minneriya, Kaudulla, or Eco Park if local conditions suit.', 'Sigiriya or Habarana', 'Local loop 1-3 hours plus visits'),
('sri-lanka-family-itinerary-10-days', 4, 4, 'Kandy gardens and temple area', 'Move to Kandy with stops that work for families, such as gardens, fruit, crafts, or short viewpoints. Keep temple or lake time short and well timed.', 'Kandy', 'Sigiriya to Kandy 2.5-3.5 hours'),
('sri-lanka-family-itinerary-10-days', 5, 5, 'Nuwara Eliya light hill day', 'Use the tea country for cooler weather, waterfalls, short walks, and a tea stop. Avoid stacking too many adult sightseeing stops into the hill-country transfer.', 'Nuwara Eliya or tea country', 'Kandy to Nuwara Eliya 2.5-3.5 hours'),
('sri-lanka-family-itinerary-10-days', 6, 6, 'Udawalawe transfer and elephant focus', 'Travel toward Udawalawe, one of the more family-friendly safari choices for elephant-focused viewing. Add the Elephant Transit Home only if the public feeding schedule and route timing fit.', 'Udawalawe', 'Tea country to Udawalawe 3.5-5 hours'),
('sri-lanka-family-itinerary-10-days', 7, 7, 'Udawalawe safari and Galle transfer', 'Take a morning or afternoon safari, then continue toward Galle or Unawatuna. Keep lunch and rest breaks flexible after the wildlife drive.', 'Galle or Unawatuna', 'Udawalawe to Galle 3.5-4.5 hours'),
('sri-lanka-family-itinerary-10-days', 8, 8, 'Galle Fort and Unawatuna', 'Use Galle Fort for a short heritage walk, then shift to beach, pool, or simple coastal time. This day should feel easier than the travel days before it.', 'Galle, Unawatuna, or south coast', 'Local coastal travel'),
('sri-lanka-family-itinerary-10-days', 9, 9, 'Bentota or south-west beach day', 'Choose a beach and pool day around Bentota, Unawatuna, Hikkaduwa, or Weligama depending on season and child ages. Keep it flexible for weather and swimming conditions.', 'South or west coast', 'Local or short coastal transfer'),
('sri-lanka-family-itinerary-10-days', 10, 10, 'Airport departure', 'Return toward Colombo or the airport with snack stops and a safe flight buffer. Do not add a long final excursion unless the flight is late at night.', 'Departure or Colombo', 'Coast to airport 2-4 hours'),

('sri-lanka-wildlife-itinerary-9-days', 1, 1, 'Arrival and recovery', 'Meet your chauffeur and recover near Negombo or Colombo. Keep the day light before the wildlife-focused route begins.', 'Negombo or Colombo', 'Airport transfer 20-90 minutes'),
('sri-lanka-wildlife-itinerary-9-days', 2, 2, 'Habarana and Sigiriya base', 'Drive to the dry-zone Cultural Triangle for Sigiriya, Habarana, or Dambulla. This positions the route near elephant-country parks without losing heritage depth.', 'Sigiriya or Habarana', 'Negombo to Sigiriya 4-5 hours'),
('sri-lanka-wildlife-itinerary-9-days', 3, 3, 'Minneriya or Kaudulla elephant safari', 'Plan Sigiriya or Dambulla in the morning, then confirm the best afternoon elephant safari park locally between Minneriya, Kaudulla, and Eco Park.', 'Sigiriya or Habarana', 'Local loop 1-3 hours plus safari'),
('sri-lanka-wildlife-itinerary-9-days', 4, 4, 'Udawalawe transfer', 'Travel south toward Udawalawe with comfort stops. This park is a practical elephant-focused anchor and a useful bridge between the Cultural Triangle, hills, and coast.', 'Udawalawe', 'Habarana to Udawalawe 5-6 hours'),
('sri-lanka-wildlife-itinerary-9-days', 5, 5, 'Udawalawe safari', 'Use a dawn or late-afternoon Udawalawe safari for elephants, birds, and dry-zone scenery. Add the Elephant Transit Home only if public timing fits without rushing.', 'Udawalawe', 'Local safari drives'),
('sri-lanka-wildlife-itinerary-9-days', 6, 6, 'Yala or Tissamaharama base', 'Continue to the Yala area, with possible Bundala wetland birding if conditions are strong. Keep the afternoon restful before a dawn safari.', 'Tissamaharama or Yala', 'Udawalawe to Yala area 3-4 hours'),
('sri-lanka-wildlife-itinerary-9-days', 7, 7, 'Yala safari and Bundala option', 'Take a dawn Yala safari for leopard-focused dry-zone wildlife expectations. If birding is a priority, use Bundala or another wetland stop as the secondary focus.', 'Tissamaharama or Yala', 'Safari-based local travel'),
('sri-lanka-wildlife-itinerary-9-days', 8, 8, 'Tangalle or Galle coastal rest', 'Move to Tangalle, Hiriketiya, Galle, or Unawatuna for a slower coast day after consecutive wildlife starts. Keep beach choice seasonal and hotel-led.', 'Tangalle, Galle, or south coast', 'Yala to coast 2-5 hours'),
('sri-lanka-wildlife-itinerary-9-days', 9, 9, 'Airport departure', 'Return by expressway or coastal route for Colombo and the airport, allowing a safe buffer after the south-coast finish.', 'Departure or Colombo', 'South coast to airport 2-4 hours'),

('sri-lanka-south-coast-itinerary-8-days', 1, 1, 'Arrival and Colombo or Negombo recovery', 'Start with a short airport transfer and an easy first night. Keep the route fresh for the coastal drive rather than sightseeing heavily on arrival.', 'Negombo or Colombo', 'Airport transfer 20-90 minutes'),
('sri-lanka-south-coast-itinerary-8-days', 2, 2, 'Galle Fort arrival', 'Travel south by expressway or coastal road and settle near Galle. Walk UNESCO-listed Galle Fort in the cooler afternoon or evening.', 'Galle or Unawatuna', 'Colombo/Negombo to Galle 2-3 hours by expressway'),
('sri-lanka-south-coast-itinerary-8-days', 3, 3, 'Unawatuna, Hikkaduwa, and reef coast', 'Use the day for Unawatuna, Hikkaduwa, Galle-area beaches, cafes, and coastal stops. Pick swimming and reef activities based on season and sea conditions.', 'Galle, Unawatuna, or Hikkaduwa', 'Local coastal travel'),
('sri-lanka-south-coast-itinerary-8-days', 4, 4, 'Weligama and Mirissa', 'Continue east toward Weligama, Ahangama, or Mirissa for surf lessons, beach cafes, and a more relaxed south-coast rhythm.', 'Weligama or Mirissa', 'Galle to Mirissa 1-2 hours'),
('sri-lanka-south-coast-itinerary-8-days', 5, 5, 'Mirissa whale watching or beach day', 'Use Mirissa for whale watching only in the right season and sea conditions, otherwise keep the day for beach, food, surf, and local coastal stops.', 'Mirissa, Weligama, or south coast', 'Local coastal travel'),
('sri-lanka-south-coast-itinerary-8-days', 6, 6, 'Tangalle and Hiriketiya', 'Move to Tangalle, Hiriketiya, or a quieter beach base for a softer coastal day. This works well for couples, families, and slower beach-focused trips.', 'Tangalle or Hiriketiya', 'Mirissa to Tangalle 1.5-2.5 hours'),
('sri-lanka-south-coast-itinerary-8-days', 7, 7, 'Udawalawe or Yala safari option', 'Add one wildlife day from the coast: Udawalawe for elephant-focused comfort or Yala for a leopard-focused dry-zone plan. Keep the exact park choice matched to hotel location and timings.', 'Udawalawe, Yala, or south coast', 'Coast to safari base 2-4 hours'),
('sri-lanka-south-coast-itinerary-8-days', 8, 8, 'Airport or Colombo return', 'Return toward Colombo, Negombo, or the airport with an expressway buffer. Add a short final stop only if the flight time allows.', 'Departure or Colombo', 'South coast to airport 2-4 hours'),

('sri-lanka-east-coast-itinerary-10-days', 1, 1, 'Arrival and recovery', 'Begin with airport pickup and a light night near Negombo or Colombo. This keeps the first day practical before the longer Cultural Triangle transfer.', 'Negombo or Colombo', 'Airport transfer 20-90 minutes'),
('sri-lanka-east-coast-itinerary-10-days', 2, 2, 'Sigiriya transfer', 'Drive to Sigiriya or Habarana and settle into a Cultural Triangle base. Add Dambulla Cave Temple if flight recovery and timing make it comfortable.', 'Sigiriya or Habarana', 'Negombo to Sigiriya 4-5 hours'),
('sri-lanka-east-coast-itinerary-10-days', 3, 3, 'Sigiriya, Dambulla, and elephant option', 'Use the day for Sigiriya Rock or Pidurangala, Dambulla, and a flexible afternoon elephant safari at Minneriya, Kaudulla, or Eco Park if local conditions suit.', 'Sigiriya or Habarana', 'Local loop 1-3 hours plus visits'),
('sri-lanka-east-coast-itinerary-10-days', 4, 4, 'Polonnaruwa to Trincomalee', 'Add Polonnaruwa for ancient-city heritage before moving to Trincomalee, Nilaveli, or Uppuveli for the east-coast beach section.', 'Trincomalee, Nilaveli, or Uppuveli', 'Sigiriya to Trincomalee via Polonnaruwa 4-5.5 hours'),
('sri-lanka-east-coast-itinerary-10-days', 5, 5, 'Nilaveli, Uppuveli, and Pigeon Island option', 'Keep the first east-coast day for beach time, snorkelling or Pigeon Island only when marine conditions and local regulations allow, and a slower seaside evening.', 'Trincomalee, Nilaveli, or Uppuveli', 'Local coastal travel'),
('sri-lanka-east-coast-itinerary-10-days', 6, 6, 'Koneswaram and Trincomalee coast', 'Use Trincomalee for Koneswaram Temple, Fort Frederick area, harbour views, and beach time. Keep activities weather-aware during the east-coast season.', 'Trincomalee, Nilaveli, or Uppuveli', 'Local Trincomalee travel'),
('sri-lanka-east-coast-itinerary-10-days', 7, 7, 'Passikudah or Batticaloa', 'Move south to Passikudah for a calmer resort-style beach base or continue toward Batticaloa for lagoon and town context. This extends the east-coast route without rushing.', 'Passikudah or Batticaloa', 'Trincomalee to Passikudah 2.5-3.5 hours'),
('sri-lanka-east-coast-itinerary-10-days', 8, 8, 'Arugam Bay or extra Passikudah rest', 'Choose Arugam Bay for surf-focused travellers and mid-year beach culture, or keep an extra Passikudah rest day for families and resort comfort.', 'Arugam Bay, Passikudah, or Batticaloa', 'Passikudah to Arugam Bay 3.5-4.5 hours'),
('sri-lanka-east-coast-itinerary-10-days', 9, 9, 'Inland return via Kandy or Negombo', 'Start the return inland with a Kandy, Dambulla, or Negombo positioning night depending on the chosen east-coast base. This prevents a stressful final-day dash.', 'Kandy, Dambulla, Negombo, or Colombo', 'East coast to inland stop 4-7 hours'),
('sri-lanka-east-coast-itinerary-10-days', 10, 10, 'Airport departure', 'Complete the final airport transfer with a safe buffer. Add a short food, shopping, or city stop only if the route and flight time allow it.', 'Departure', 'Final transfer varies by overnight base'),

('sri-lanka-luxury-itinerary-11-days', 1, 1, 'VIP arrival and soft landing', 'Begin with private airport handling style, a comfortable vehicle, and a boutique Colombo or Negombo stay. Keep the day focused on recovery, food, and room quality.', 'Colombo or Negombo', 'Airport transfer 20-90 minutes'),
('sri-lanka-luxury-itinerary-11-days', 2, 2, 'Sigiriya luxury lodge', 'Travel to the Cultural Triangle and check into a lodge or high-comfort base. Add Dambulla or a private local experience only if it protects the property time.', 'Sigiriya or Habarana', 'Colombo/Negombo to Sigiriya 4-5 hours'),
('sri-lanka-luxury-itinerary-11-days', 3, 3, 'Private Sigiriya and heritage guiding', 'Use a privately guided day for Sigiriya, Pidurangala, Dambulla, Polonnaruwa, or local dining, choosing fewer stops with better context instead of a checklist.', 'Sigiriya or Habarana', 'Local Cultural Triangle travel'),
('sri-lanka-luxury-itinerary-11-days', 4, 4, 'Kandy or tea country transition', 'Move toward Kandy or directly into tea country based on hotel choice. Add gardens, the Temple of the Sacred Tooth Relic area, or a scenic lunch with unhurried timing.', 'Kandy or tea country', 'Sigiriya to Kandy 2.5-3.5 hours'),
('sri-lanka-luxury-itinerary-11-days', 5, 5, 'Tea bungalow and highland scenery', 'Use the tea country for a bungalow stay, estate walk, tea tasting, waterfalls, and cooler evenings. The plan should protect time at the property.', 'Nuwara Eliya, Hatton, or tea country', 'Kandy to tea country 2.5-4 hours'),
('sri-lanka-luxury-itinerary-11-days', 6, 6, 'Ella or Haputale scenic day', 'Continue through highland scenery with a selected train segment or private scenic drive if timing is strong. Add Nine Arch Bridge, viewpoints, or a soft hike.', 'Ella, Haputale, or tea country', 'Tea country to Ella 2-4 hours'),
('sri-lanka-luxury-itinerary-11-days', 7, 7, 'Safari lodge transfer', 'Descend to Yala, Udawalawe, or a safari lodge area. Choose the park and lodge around wildlife goals, comfort, and the desired south-coast finish.', 'Yala, Udawalawe, or safari lodge', 'Ella/tea country to safari base 2.5-5 hours'),
('sri-lanka-luxury-itinerary-11-days', 8, 8, 'Private safari and Tangalle wellness', 'Take a dawn or late-afternoon safari, then continue to Tangalle, Hiriketiya, or a wellness-led coastal stay with enough rest after the early drive.', 'Tangalle, Hiriketiya, or south coast', 'Safari base to coast 2-4 hours'),
('sri-lanka-luxury-itinerary-11-days', 9, 9, 'Galle boutique stay', 'Move to Galle for a boutique Fort stay, private walk, food, architecture, and a curated south-coast evening. Keep the day selective and polished.', 'Galle or south coast', 'Tangalle to Galle 2-3 hours'),
('sri-lanka-luxury-itinerary-11-days', 10, 10, 'Beach, villa, or wellness day', 'Protect one full luxury slow day for spa time, private dining, a villa stay, beach, seasonal whale watching, or a curated coastal experience.', 'Galle, Bentota, Tangalle, or south coast', 'Local or short coastal transfer'),
('sri-lanka-luxury-itinerary-11-days', 11, 11, 'Airport departure with buffer', 'Return by expressway or private transfer route for Colombo or the airport. Keep final stops optional and time-safe.', 'Departure or Colombo', 'Coast to airport 2-4 hours'),

('sri-lanka-birding-nature-itinerary-12-days', 1, 1, 'Arrival and wetland edge recovery', 'Arrive near Negombo or Colombo with an optional light wetland, lagoon, or garden-style start if flight timing allows. Keep the first day quiet before specialist nature travel.', 'Negombo or Colombo', 'Airport transfer 20-90 minutes'),
('sri-lanka-birding-nature-itinerary-12-days', 2, 2, 'Ratnapura or Sinharaja approach', 'Travel toward the rainforest edge via Ratnapura or a Sinharaja gateway. The day is mainly positioning, with late light and weather determining any short nature stop.', 'Sinharaja gateway or Ratnapura area', 'Negombo/Colombo to Sinharaja edge 4-5.5 hours'),
('sri-lanka-birding-nature-itinerary-12-days', 3, 3, 'Sinharaja rainforest', 'Use an early start with a local guide for Sinharaja rainforest habitats, endemic birds, plants, and wet-zone wildlife. Expect weather flexibility and slower forest movement.', 'Sinharaja gateway', 'Local rainforest travel'),
('sri-lanka-birding-nature-itinerary-12-days', 4, 4, 'Udawalawe dry-zone transition', 'Move from rainforest toward Udawalawe to add dry-zone habitats and elephant-focused wildlife. Keep the transfer practical with stops selected for birding potential.', 'Udawalawe', 'Sinharaja edge to Udawalawe 3-5 hours'),
('sri-lanka-birding-nature-itinerary-12-days', 5, 5, 'Udawalawe safari and Bundala approach', 'Use Udawalawe for elephants, raptors, waterbirds, and dry-zone scenery, then continue toward Bundala or Tissamaharama if the birding plan calls for wetlands.', 'Tissamaharama, Bundala area, or Udawalawe', 'Udawalawe to Bundala/Tissamaharama 2.5-4 hours'),
('sri-lanka-birding-nature-itinerary-12-days', 6, 6, 'Bundala and Yala wetland-dry-zone mix', 'Plan Bundala for wetland and coastal birding or combine with a Yala-area dry-zone wildlife window depending on seasonal conditions and guide advice.', 'Tissamaharama, Bundala, or Yala area', 'Local wetland and safari travel'),
('sri-lanka-birding-nature-itinerary-12-days', 7, 7, 'Horton Plains or Nuwara Eliya transfer', 'Travel into the highlands for Horton Plains, Nuwara Eliya, or surrounding cloud-forest habitats. This adds a very different elevation and climate to the nature route.', 'Nuwara Eliya or highlands', 'Tissamaharama/Yala to Nuwara Eliya 5-6 hours'),
('sri-lanka-birding-nature-itinerary-12-days', 8, 8, 'Highland habitat day', 'Use an early highland start for Horton Plains, Victoria Park, tea-country edges, or cloud-forest habitat depending on access, weather, and guide recommendations.', 'Nuwara Eliya or highlands', 'Local highland travel'),
('sri-lanka-birding-nature-itinerary-12-days', 9, 9, 'Kandy and Knuckles foothills', 'Move toward Kandy or the Knuckles foothills for botanical, forest-edge, and cultural landscape variety. Keep the nature stops focused rather than city-heavy.', 'Kandy or Knuckles foothills', 'Nuwara Eliya to Kandy 2.5-4 hours'),
('sri-lanka-birding-nature-itinerary-12-days', 10, 10, 'Forest edge or coastal nature return', 'Choose a second forest-edge morning, a botanical stop, or a move toward Galle and the coast depending on the selected habitats and departure plan.', 'Kandy, Galle, or west/south coast', 'Route varies by chosen habitat'),
('sri-lanka-birding-nature-itinerary-12-days', 11, 11, 'Flexible specialist nature day', 'Keep one buffer day for repeat birding, photography, weather recovery, wetlands, or a slower coastal nature finish. Specialist nature routes need this flexibility.', 'Galle, Negombo, or selected nature base', 'Local or positioning travel'),
('sri-lanka-birding-nature-itinerary-12-days', 12, 12, 'Airport departure', 'Return to the airport with a safe buffer, using any final stop only if it is close to the route and does not compromise check-in timing.', 'Departure', 'Final transfer varies by overnight base');

INSERT INTO itinerary_days
    (itinerary_id, day_number, day_end, title, summary, overnight_location, travel_time)
SELECT
    i.id,
    s.day_number,
    s.day_end,
    s.title,
    s.summary,
    s.overnight_location,
    s.travel_time
FROM ict_itinerary_day_seed s
INNER JOIN itineraries i ON i.slug = s.itinerary_slug
ON DUPLICATE KEY UPDATE
    day_end = VALUES(day_end),
    title = VALUES(title),
    summary = VALUES(summary),
    overnight_location = VALUES(overnight_location),
    travel_time = VALUES(travel_time),
    updated_at = CURRENT_TIMESTAMP;

DROP TEMPORARY TABLE IF EXISTS ict_itinerary_day_seed;
